def signature_projection(document):
 try:
  from scripts.baseline.r2_quote_preparation_transport_contract import preparation_projection
 except ModuleNotFoundError:
  from r2_quote_preparation_transport_contract import preparation_projection
 result=preparation_projection(document);paths=result['paths'];schemas=result['components']['schemas']
 if not any(k in paths for k in PATHS) and not any(k in schemas for k in SCHEMAS):return result
 for section,pins in ((paths,PATHS),(schemas,SCHEMAS)):
  for key,pin in pins.items():
   if digest(section.pop(key,None))!=pin:raise ValueError('T09 exact manual signature contract required: '+key)
 for key,pin in CHANGED.items():
  if digest(schemas[key])!=pin:raise ValueError('T09 exact manual signature addition required: '+key)
  schemas[key]=deepcopy(PREVIOUS[key])
